root.addEventListener('click', e => {
  const pageBtn=e.target.closest('[data-page]'); if(pageBtn){page=pageBtn.dataset.page;render();return;}
  const el=e.target.closest('[data-action]'); if(!el)return;
  const a=el.dataset.action;
  if(a==='day') game.advance();
  if(a==='save') game.manualSave();
  if(a==='hire') game.employees.hire(el.dataset.role);
  if(a==='train') game.employees.train(el.dataset.id);
  if(a==='fire') {if(confirm('Let this teammate go?'))game.employees.fire(el.dataset.id);}
  if(a==='expand') game.office.expand();
  if(a==='decorate') game.office.decorate();
  if(a==='research') game.research.unlock(el.dataset.id);
  if(a==='campaign') game.marketing.launch(el.dataset.type);
  if(a==='focus-form') document.querySelector('#project-form')?.scrollIntoView({behavior:'smooth',block:'center'});
  if(a==='reset') {if(confirm('Start a new studio? This replaces your saved company on this device.')){const name=prompt('What will your studio be called?','Pixel Pioneers');if(name!==null){game.newGame(name);page='Overview';render();toastMsg('A new studio journey begins!');}}}
});
root.addEventListener('submit',e=>{
  if(e.target.id!=='new-game-form')return; e.preventDefault(); const f=new FormData(e.target);
  game.development.start({title:f.get('title'),genre:f.get('genre'),platform:f.get('platform'),size:f.get('size'),graphics:Number(f.get('graphics')),features:f.getAll('features')});
});
root.addEventListener('input',e=>{if(e.target.name==='graphics'){const out=root.querySelector('#quality-value');if(out)out.textContent=e.target.value;}});
